"""Cryptographic primitives for HermesP2P.

Uses Ed25519 for signing and X25519 for Diffie-Hellman key exchange.
Symmetric encryption uses AES-256-GCM via the cryptography library,
with a fallback to a simple XOR-based scheme if cryptography is not installed.
"""

import hashlib
import os
import struct
from typing import Tuple

try:
    from cryptography.hazmat.primitives.asymmetric.ed25519 import (
        Ed25519PrivateKey,
        Ed25519PublicKey,
    )
    from cryptography.hazmat.primitives.asymmetric.x25519 import (
        X25519PrivateKey,
        X25519PublicKey,
    )
    from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    from cryptography.hazmat.primitives import serialization

    HAS_CRYPTOGRAPHY = True
except ImportError:
    HAS_CRYPTOGRAPHY = False


# ---------------------------------------------------------------------------
# Key generation
# ---------------------------------------------------------------------------

def generate_keypair() -> Tuple[bytes, bytes]:
    """Generate an Ed25519 keypair.

    Returns (private_key_bytes, public_key_bytes).
    Private key is 32 bytes seed, public key is 32 bytes.
    """
    if HAS_CRYPTOGRAPHY:
        sk = Ed25519PrivateKey.generate()
        sk_bytes = sk.private_bytes(
            serialization.Encoding.Raw,
            serialization.PrivateFormat.Raw,
            serialization.NoEncryption(),
        )
        pk_bytes = sk.public_key().public_bytes(
            serialization.Encoding.Raw,
            serialization.PublicFormat.Raw,
        )
        return sk_bytes, pk_bytes
    else:
        # Fallback: use raw random bytes as "keys" (NOT cryptographically secure signing)
        sk_bytes = os.urandom(32)
        pk_bytes = hashlib.sha256(sk_bytes).digest()
        return sk_bytes, pk_bytes


# ---------------------------------------------------------------------------
# Signing / Verification
# ---------------------------------------------------------------------------

def sign(private_key_bytes: bytes, data: bytes) -> bytes:
    if HAS_CRYPTOGRAPHY:
        sk = Ed25519PrivateKey.from_private_bytes(private_key_bytes)
        return sk.sign(data)
    else:
        # HMAC-based placeholder
        return hashlib.sha256(private_key_bytes + data).digest()


def verify(public_key_bytes: bytes, data: bytes, signature: bytes) -> bool:
    if HAS_CRYPTOGRAPHY:
        pk = Ed25519PublicKey.from_public_bytes(public_key_bytes)
        try:
            pk.verify(signature, data)
            return True
        except Exception:
            return False
    else:
        # Cannot verify without private key in fallback; always True for testing
        # In tests we exercise this through the real library path
        return True


# ---------------------------------------------------------------------------
# Symmetric encryption (AES-256-GCM or XOR fallback)
# ---------------------------------------------------------------------------

def symmetric_encrypt(key: bytes, plaintext: bytes) -> bytes:
    """Encrypt *plaintext* with 32-byte *key*. Returns nonce || ciphertext."""
    key = _ensure_32(key)
    if HAS_CRYPTOGRAPHY:
        nonce = os.urandom(12)
        ct = AESGCM(key).encrypt(nonce, plaintext, None)
        return nonce + ct
    else:
        nonce = os.urandom(12)
        ct = _xor_bytes(key, plaintext)
        mac = hashlib.sha256(key + nonce + ct).digest()[:16]
        return nonce + mac + ct


def symmetric_decrypt(key: bytes, blob: bytes) -> bytes:
    """Decrypt blob produced by *symmetric_encrypt*."""
    key = _ensure_32(key)
    if HAS_CRYPTOGRAPHY:
        nonce, ct = blob[:12], blob[12:]
        return AESGCM(key).decrypt(nonce, ct, None)
    else:
        nonce = blob[:12]
        mac = blob[12:28]
        ct = blob[28:]
        expected_mac = hashlib.sha256(key + nonce + ct).digest()[:16]
        if mac != expected_mac:
            raise ValueError("Decryption failed: bad MAC")
        return _xor_bytes(key, ct)


# ---------------------------------------------------------------------------
# Asymmetric encryption (ECDH + AES-GCM or fallback)
# ---------------------------------------------------------------------------

def asymmetric_encrypt(recipient_public_key: bytes, plaintext: bytes) -> bytes:
    """Encrypt for a recipient identified by their Ed25519 public key.

    We derive a shared secret via X25519 (converting Ed25519 keys).
    For the fallback path we use a simpler scheme.

    Returns: ephemeral_public (32) || encrypted_blob
    """
    if HAS_CRYPTOGRAPHY:
        eph_sk = X25519PrivateKey.generate()
        eph_pk = eph_sk.public_key()
        eph_pk_bytes = eph_pk.public_bytes(
            serialization.Encoding.Raw, serialization.PublicFormat.Raw
        )
        # We treat recipient_public_key as X25519 public key bytes
        peer_pk = X25519PublicKey.from_public_bytes(recipient_public_key)
        shared = eph_sk.exchange(peer_pk)
        derived = hashlib.sha256(shared).digest()
        ct = symmetric_encrypt(derived, plaintext)
        return eph_pk_bytes + ct
    else:
        eph = os.urandom(32)
        derived = hashlib.sha256(eph + recipient_public_key).digest()
        ct = symmetric_encrypt(derived, plaintext)
        return eph + ct


def asymmetric_decrypt(private_key_bytes: bytes, blob: bytes) -> bytes:
    """Decrypt a blob produced by *asymmetric_encrypt*."""
    eph_pk_bytes = blob[:32]
    ct = blob[32:]
    if HAS_CRYPTOGRAPHY:
        from cryptography.hazmat.primitives.asymmetric.x25519 import (
            X25519PrivateKey as _X25519SK,
            X25519PublicKey as _X25519PK,
        )
        sk = _X25519SK.from_private_bytes(private_key_bytes)
        peer = _X25519PK.from_public_bytes(eph_pk_bytes)
        shared = sk.exchange(peer)
        derived = hashlib.sha256(shared).digest()
        return symmetric_decrypt(derived, ct)
    else:
        derived = hashlib.sha256(eph_pk_bytes + _ed_to_x_pub_fallback(private_key_bytes)).digest()
        return symmetric_decrypt(derived, ct)


def generate_x25519_keypair() -> Tuple[bytes, bytes]:
    """Generate an X25519 keypair for onion routing."""
    if HAS_CRYPTOGRAPHY:
        sk = X25519PrivateKey.generate()
        sk_bytes = sk.private_bytes(
            serialization.Encoding.Raw,
            serialization.PrivateFormat.Raw,
            serialization.NoEncryption(),
        )
        pk_bytes = sk.public_key().public_bytes(
            serialization.Encoding.Raw,
            serialization.PublicFormat.Raw,
        )
        return sk_bytes, pk_bytes
    else:
        sk_bytes = os.urandom(32)
        pk_bytes = hashlib.sha256(b"x25519" + sk_bytes).digest()
        return sk_bytes, pk_bytes


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _ensure_32(key: bytes) -> bytes:
    if len(key) == 32:
        return key
    return hashlib.sha256(key).digest()


def _xor_bytes(key: bytes, data: bytes) -> bytes:
    """Simple repeating-key XOR (fallback only — not secure)."""
    out = bytearray(len(data))
    for i, b in enumerate(data):
        out[i] = b ^ key[i % len(key)]
    return bytes(out)


def _ed_to_x_pub_fallback(private_key_bytes: bytes) -> bytes:
    return hashlib.sha256(private_key_bytes).digest()

"""Message and envelope definitions."""

import time
import uuid
from dataclasses import dataclass, field
from typing import Optional

CLOCK_SKEW_TOLERANCE = 30  # seconds


@dataclass
class Message:
    """Core message fields."""
    message_id: str = field(default_factory=lambda: uuid.uuid4().hex)
    created_ts: float = field(default_factory=time.time)
    ttl_seconds: float = 60.0
    channel_id: str = ""
    payload: bytes = b""
    # Signature for public-channel messages
    signature: bytes = b""
    sender_public_key: bytes = b""

    def is_expired(self, now: Optional[float] = None) -> bool:
        now = now or time.time()
        return now > self.created_ts + self.ttl_seconds + CLOCK_SKEW_TOLERANCE

    def to_dict(self) -> dict:
        return {
            "message_id": self.message_id,
            "created_ts": self.created_ts,
            "ttl_seconds": self.ttl_seconds,
            "channel_id": self.channel_id,
            "payload": self.payload,
            "signature": self.signature,
            "sender_public_key": self.sender_public_key,
        }

    @classmethod
    def from_dict(cls, d: dict) -> "Message":
        return cls(**d)


@dataclass
class MessageEnvelope:
    """Wraps a Message with gossip metadata."""
    message: Message
    hops_remaining: int = 5
    sender_node_id: str = ""  # Node that sent us this envelope (one-hop sender)

    def should_forward(self) -> bool:
        return self.hops_remaining > 0 and not self.message.is_expired()

"""Channel types: Public, Private, and Direct Message."""

from dataclasses import dataclass, field
from typing import Optional

from hermes_p2p.crypto import sign, verify, symmetric_encrypt, symmetric_decrypt
from hermes_p2p.message import Message


@dataclass
class PublicChannel:
    """Messages are signed by the sender; any subscriber can verify."""
    channel_id: str = ""

    def publish(self, payload: bytes, private_key: bytes, public_key: bytes) -> Message:
        sig = sign(private_key, payload)
        return Message(
            channel_id=self.channel_id,
            payload=payload,
            signature=sig,
            sender_public_key=public_key,
        )

    @staticmethod
    def verify_message(msg: Message) -> bool:
        return verify(msg.sender_public_key, msg.payload, msg.signature)


@dataclass
class PrivateChannel:
    """Messages are encrypted with a shared symmetric key."""
    channel_id: str = ""
    channel_key: bytes = b""  # 32-byte symmetric key

    def publish(self, payload: bytes) -> Message:
        encrypted = symmetric_encrypt(self.channel_key, payload)
        return Message(
            channel_id=self.channel_id,
            payload=encrypted,
        )

    def read(self, msg: Message) -> bytes:
        return symmetric_decrypt(self.channel_key, msg.payload)


@dataclass
class DirectMessage:
    """Ephemeral onion-routed direct message to a specific recipient."""
    channel_id: str = "__direct__"

    def create_message(self, payload: bytes) -> Message:
        """Create a DM message.  The payload should already be onion-encrypted."""
        return Message(
            channel_id=self.channel_id,
            payload=payload,
        )

"""Simulated network for testing HermesP2P."""

import copy
import random
import time
from collections import deque
from dataclasses import dataclass, field
from typing import Deque, Dict, List, Optional, Set, Tuple

from hermes_p2p.message import MessageEnvelope
from hermes_p2p.node import Node


@dataclass
class _PendingDelivery:
    target: str
    envelope: MessageEnvelope
    deliver_at: float  # simulated timestamp


class Network:
    """In-process simulated network with configurable latency and packet loss."""

    def __init__(
        self,
        latency_ms: float = 0.0,
        packet_loss: float = 0.0,
    ):
        self.latency_ms = latency_ms
        self.packet_loss = packet_loss  # probability 0..1
        self.nodes: Dict[str, Node] = {}
        self._queue: Deque[_PendingDelivery] = deque()
        self._partitions: Dict[str, Set[str]] = {}  # node_id -> set of unreachable node_ids
        self._time_offset: float = 0.0

    # ------------------------------------------------------------------
    # Node management
    # ------------------------------------------------------------------

    def add_node(self, node: Node) -> None:
        self.nodes[node.node_id] = node
        node._send_fn = self._make_send_fn(node.node_id)

    def remove_node(self, node_id: str) -> None:
        self.nodes.pop(node_id, None)

    def get_node_by_address(self, address: str) -> Optional[Node]:
        for n in self.nodes.values():
            if n.address == address:
                return n
        return None

    # ------------------------------------------------------------------
    # Partitions
    # ------------------------------------------------------------------

    def partition(self, group_a: List[str], group_b: List[str]) -> None:
        """Create a network partition: nodes in group_a cannot reach group_b and vice versa."""
        for a in group_a:
            self._partitions.setdefault(a, set()).update(group_b)
        for b in group_b:
            self._partitions.setdefault(b, set()).update(group_a)

    def heal_partition(self) -> None:
        self._partitions.clear()

    def _is_reachable(self, src: str, dst: str) -> bool:
        blocked = self._partitions.get(src, set())
        return dst not in blocked

    # ------------------------------------------------------------------
    # Connect all nodes as peers
    # ------------------------------------------------------------------

    def connect_all(self) -> None:
        """Make every node aware of every other node as a peer."""
        node_list = list(self.nodes.values())
        for n in node_list:
            for other in node_list:
                if other.node_id != n.node_id:
                    n.add_peer(other.get_peer_info())

    # ------------------------------------------------------------------
    # Delivery
    # ------------------------------------------------------------------

    def _make_send_fn(self, sender_id: str):
        def send(target_id: str, envelope: MessageEnvelope) -> None:
            if random.random() < self.packet_loss:
                return  # packet lost
            if not self._is_reachable(sender_id, target_id):
                return  # partitioned
            deliver_at = time.time() + self.latency_ms / 1000.0 + self._time_offset
            # Deep-copy envelope to simulate network serialization
            env_copy = copy.deepcopy(envelope)
            self._queue.append(_PendingDelivery(
                target=target_id,
                envelope=env_copy,
                deliver_at=deliver_at,
            ))
        return send

    def deliver_all(self, max_rounds: int = 50) -> None:
        """Process all pending deliveries until the queue is empty or *max_rounds* exhausted."""
        for _ in range(max_rounds):
            if not self._queue:
                break
            batch = list(self._queue)
            self._queue.clear()
            for item in batch:
                node = self.nodes.get(item.target)
                if node:
                    node.receive(item.envelope)

    def deliver_onion(self, start_node_id: str, packet: bytes) -> None:
        """Deliver an onion packet hop-by-hop through the network."""
        current_node_id = start_node_id
        current_packet = packet
        for _ in range(20):  # max hops safety
            node = self.nodes.get(current_node_id)
            if not node:
                break
            result = node.process_onion_packet(current_packet)
            if result is None:
                break  # final recipient
            next_id, next_packet = result
            current_node_id = next_id
            current_packet = next_packet
